import{_ as t,o as a,c as n,ag as s}from"./chunks/framework.8tqBsFWt.js";const u=JSON.parse('{"title":"Tenant Offboarding Runbook","description":"","frontmatter":{},"headers":[],"relativePath":"operations/offboarding.md","filePath":"operations/offboarding.md"}'),o={name:"operations/offboarding.md"};function i(r,e,l,d,h,p){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="tenant-offboarding-runbook" tabindex="-1">Tenant Offboarding Runbook <a class="header-anchor" href="#tenant-offboarding-runbook" aria-label="Permalink to &quot;Tenant Offboarding Runbook&quot;">​</a></h1><p>Use this runbook when a client&#39;s subscription ends and their data and credentials need to be removed from VERA.</p><hr><h2 id="when-to-offboard" tabindex="-1">When to offboard <a class="header-anchor" href="#when-to-offboard" aria-label="Permalink to &quot;When to offboard&quot;">​</a></h2><p>Offboard a tenant when:</p><ul><li>A client subscription has ended and they will not be returning.</li><li>A test or demo tenant is no longer needed.</li><li>A tenant was created by mistake and has never been used.</li></ul><p>Do <strong>not</strong> offboard a tenant that is temporarily inactive — simply stop sending them the Slack reminders and leave the configuration intact.</p><hr><h2 id="the-script" tabindex="-1">The script <a class="header-anchor" href="#the-script" aria-label="Permalink to &quot;The script&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/offboard-tenant.js</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tenant=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--dry-run] [--skip-pg] [--out</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dir</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Flag</th><th>Effect</th></tr></thead><tbody><tr><td><code>--tenant=&lt;id&gt;</code></td><td><strong>Required.</strong> The tenant id (matches the id field in the tenants file).</td></tr><tr><td><code>--dry-run</code></td><td>Walks the entire flow, prints what would happen, writes nothing. Run this first.</td></tr><tr><td><code>--skip-pg</code></td><td>Skips the Postgres export and deletion pass. Use only if you know the tenant was never added to <code>PG_SHADOW_WRITE_TENANTS</code>.</td></tr><tr><td><code>--out=&lt;dir&gt;</code></td><td>Custom path for the backup bundle. Default: <code>./offboarded-tenants/&lt;id&gt;-&lt;YYYY-MM-DD-HHmmss&gt;/</code>.</td></tr><tr><td><code>--allow-partial-export</code></td><td><strong>Danger.</strong> If one or more sheet tabs fail to export, proceed to the confirmation gate anyway instead of aborting. The bundle README marks each failed tab as &quot;EXPORT FAILED&quot;. Do not use this unless you are certain the failed data is unrecoverable or expendable.</td></tr></tbody></table><h3 id="recommended-sequence" tabindex="-1">Recommended sequence <a class="header-anchor" href="#recommended-sequence" aria-label="Permalink to &quot;Recommended sequence&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Dry run first — inspect the output, verify row counts look right</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/offboard-tenant.js</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tenant=acme</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Real run — type the tenant id when prompted to confirm</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/offboard-tenant.js</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tenant=acme</span></span></code></pre></div><hr><h2 id="what-the-script-does" tabindex="-1">What the script does <a class="header-anchor" href="#what-the-script-does" aria-label="Permalink to &quot;What the script does&quot;">​</a></h2><p>The script is built around a single principle: <strong>do no harm</strong>. Every byte of the tenant&#39;s data is exported to a portable bundle before anything is deleted. If you change your mind, abort at the confirmation prompt and the bundle stays on disk.</p><h3 id="step-by-step" tabindex="-1">Step-by-step <a class="header-anchor" href="#step-by-step" aria-label="Permalink to &quot;Step-by-step&quot;">​</a></h3><ol><li><p><strong>Pre-flight</strong> — Loads the tenant from the tenants file. Prints a summary (sheet id, audit channel, pg status). Fails fast if the tenant id is not found.</p></li><li><p><strong>Sheets export</strong> — Fetches all 14 operational tabs from the tenant&#39;s Google Sheet using their own service account credentials. Each tab is written as a CSV in <code>&lt;bundle&gt;/sheets/</code>.</p></li><li><p><strong>Postgres export</strong> (if applicable) — If the tenant is in <code>PG_SHADOW_WRITE_TENANTS</code>, reads all 14 tables from Postgres and writes them as CSVs in <code>&lt;bundle&gt;/postgres/</code>.</p></li><li><p><strong>Tenant config</strong> — Writes two files in <code>&lt;bundle&gt;/meta/</code>:</p><ul><li><code>tenant-config.json</code> — sanitised, safe to share with the client. Credentials are stripped.</li><li><code>tenant-config.full.json</code> — full record including tokens and service account key. <strong>Internal only — do not share.</strong></li></ul></li><li><p><strong>Bundle README</strong> — Writes <code>&lt;bundle&gt;/meta/README.md</code> describing the bundle contents with row counts.</p></li><li><p><strong>Confirmation gate</strong> — Prints a summary of what was exported and asks you to type the tenant id to proceed. Anything else aborts.</p></li><li><p><strong>Postgres deletion</strong> — Deletes all rows for this tenant from all 14 tables inside a single transaction. Rolls back on any error.</p></li><li><p><strong>Tenants file mutation</strong> — Removes the tenant entry from the tenants file (<code>TENANTS_FILE</code> env var, defaults to <code>tenants.dev.json</code>).</p></li><li><p><strong>Manual checklist</strong> — Prints the steps that cannot be automated (see below).</p></li></ol><hr><h2 id="bundle-layout" tabindex="-1">Bundle layout <a class="header-anchor" href="#bundle-layout" aria-label="Permalink to &quot;Bundle layout&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>offboarded-tenants/&lt;tenant-id&gt;-&lt;YYYY-MM-DD-HHmmss&gt;/</span></span>
<span class="line"><span>  sheets/</span></span>
<span class="line"><span>    01-time-entries.csv</span></span>
<span class="line"><span>    02-projects.csv</span></span>
<span class="line"><span>    ... (14 files total)</span></span>
<span class="line"><span>  postgres/               (only present if tenant was pg-allowlisted)</span></span>
<span class="line"><span>    time_entries.csv</span></span>
<span class="line"><span>    projects.csv</span></span>
<span class="line"><span>    ... (0–14 files — only tables with at least one row get a CSV)</span></span>
<span class="line"><span>  meta/</span></span>
<span class="line"><span>    tenant-config.json        ← safe to share with client</span></span>
<span class="line"><span>    tenant-config.full.json   ← INTERNAL ONLY — contains credentials</span></span>
<span class="line"><span>    README.md</span></span></code></pre></div><p>The column order of each CSV in <code>sheets/</code> matches the schema documented at <a href="https://getvera.site/reference/schema/sheets" target="_blank" rel="noreferrer">https://getvera.site/reference/schema/sheets</a></p><hr><h2 id="after-the-script-—-manual-steps" tabindex="-1">After the script — manual steps <a class="header-anchor" href="#after-the-script-—-manual-steps" aria-label="Permalink to &quot;After the script — manual steps&quot;">​</a></h2><p>The script prints this checklist at the end. Do not skip these steps.</p><ol><li><p><strong>Restart the VERA service</strong> so Bolt drops the tenant&#39;s Socket Mode connection and the in-memory tenant cache is rebuilt without them.</p></li><li><p><strong>Uninstall the Slack app</strong> from the client&#39;s workspace. The client&#39;s Slack workspace admin must do this in Slack &gt; Settings &gt; Manage apps.</p></li><li><p><strong>Revoke Google service account access</strong> to the client&#39;s Google Sheet. Either remove the service account&#39;s Editor access in the Sheet&#39;s sharing settings, or transfer ownership of the sheet back to the client.</p></li><li><p><strong>Archive the audit channel</strong> in Slack. This is the channel VERA posted notifications to — archive it so it no longer receives messages.</p></li><li><p><strong>Verify the dashboard URL</strong> returns 404. If the tenant had a <code>dashboard_slug</code>, confirm <code>https://dash.getvera.site/d/&lt;slug&gt;</code> is no longer accessible.</p></li><li><p><strong>Zip and hand over the bundle.</strong> Zip <code>offboarded-tenants/&lt;tenant-id&gt;-&lt;YYYY-MM-DD-HHmmss&gt;/</code>, but <strong>exclude <code>meta/tenant-config.full.json</code></strong> (it contains credentials). Send the zip to the client as their data handover.</p></li><li><p><strong>Remove from Railway env.</strong> If the tenant id was in <code>PG_SHADOW_WRITE_TENANTS</code>, remove it from the Railway environment variable and redeploy.</p></li></ol><hr><h2 id="if-you-change-your-mind" tabindex="-1">If you change your mind <a class="header-anchor" href="#if-you-change-your-mind" aria-label="Permalink to &quot;If you change your mind&quot;">​</a></h2><p>If you ran the script, aborted at the confirmation prompt, and then decide you want to keep the tenant:</p><ul><li>The bundle in <code>offboarded-tenants/</code> can be ignored or deleted — nothing in production was changed.</li><li>Restart VERA if you already removed the tenant id from <code>PG_SHADOW_WRITE_TENANTS</code>.</li></ul><p>If you confirmed and the script ran to completion on the same day:</p><ul><li>The Google Sheet is untouched — you still have all the data there.</li><li>The Postgres rows are gone. To restore, re-add the tenant to the tenants file, re-add to <code>PG_SHADOW_WRITE_TENANTS</code>, restart VERA, and run <code>scripts/backfill-tenant.js --tenant=&lt;id&gt;</code> to repopulate Postgres from the Sheet.</li><li>The tenants file has been mutated — restore the entry from <code>meta/tenant-config.json</code> in the bundle.</li></ul><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="a-sheet-tab-failed-to-export" tabindex="-1">A sheet tab failed to export <a class="header-anchor" href="#a-sheet-tab-failed-to-export" aria-label="Permalink to &quot;A sheet tab failed to export&quot;">​</a></h3><p>The script prints the failing tab and error message, then exits before the confirmation gate:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>❌ The following sheet tabs failed to export:</span></span>
<span class="line"><span>  02. Projects!A:T → Quota exceeded for quota metric &#39;read_requests&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Aborting — cannot proceed to deletion with an incomplete backup.</span></span>
<span class="line"><span>Fix the error above and re-run, or pass --allow-partial-export to proceed anyway.</span></span>
<span class="line"><span>Partial bundle preserved at: ./offboarded-tenants/acme-2026-05-12-143022</span></span></code></pre></div><p><strong>Recommended action:</strong> Fix the root cause (quota, permissions, connectivity) and re-run. The partial bundle on disk can be deleted — nothing in production was changed.</p><p>If the failure is truly unrecoverable and you still need to proceed, use <code>--allow-partial-export</code>. The script will continue to the confirmation gate. The bundle README will mark the failed tab(s) as <code>⚠️ EXPORT FAILED</code>. Do not hand an incomplete bundle to the client without disclosing what is missing.</p><hr><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>The script never posts to the audit channel (it is an out-of-band operator command, not a VERA action).</li><li>The script never hard-deletes the client&#39;s Google Sheet. The Sheet is owned by the client&#39;s Google account; VERA only had Editor access via the service account.</li><li><code>tenant-config.full.json</code> contains the service account key JSON and Slack tokens. Treat it like a password file.</li><li>Postgres tables with 0 rows produce no CSV file in <code>postgres/</code>. The <code>meta/README.md</code> row-count table will show <code>0</code> for those tables — that means the table was queried successfully and was empty, not that it was skipped.</li></ul>`,42)])])}const g=t(o,[["render",i]]);export{u as __pageData,g as default};
